mapper.select:
SELECT 
FROM iam_audit_log log
WHERE log.event_id = #{eventId}

SELECT 
FROM iam_audit_log log
WHERE log.id < #{maxLogId}

    AND log.action_code = #{actionCode}


    AND log.resource_type = #{resourceType}


    AND log.resource_id = #{resourceId}


    AND log.occurred_at >= #{occurredFrom}


    AND log.occurred_at <= #{occurredTo}


    AND EXISTS (SELECT 1 FROM iam_audit_subject_link link
                 WHERE link.audit_log_id = log.id
                   AND link.subject_type = 'USER'
                   AND link.subject_id = #{subjectUserId})


    AND EXISTS (SELECT 1 FROM iam_audit_subject_link link
                 WHERE link.audit_log_id = log.id
                   AND link.subject_type = 'IDENTITY'
                   AND link.subject_id = #{subjectIdentityId})


    AND EXISTS (SELECT 1 FROM iam_audit_subject_link link
                 WHERE link.audit_log_id = log.id
                   AND link.subject_type = 'SESSION'
                   AND link.subject_id = #{subjectSessionId})

ORDER BY log.id DESC
LIMIT #{limit}

SELECT audit_log_id, subject_type, subject_id, relation_code FROM iam_audit_subject_link WHERE audit_log_id IN
#{logId}
ORDER BY id
